<?php
require __DIR__.'/../../config/bootstrap.php';
Pharmacy\Auth\Authorization::requireRole('ADMIN');
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$stmt=$pdo->prepare("SELECT a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE DATE(a.created_at) BETWEEN :from AND :to ORDER BY a.id DESC LIMIT 2000");$stmt->execute(['from'=>$from,'to'=>$to]);$rows=$stmt->fetchAll();$title='Audit Log';require __DIR__.'/../../templates/header.php';?>
<h2 class="page-title">Audit Log</h2><form class="row g-2 mb-3"><div class="col-md-2"><input class="form-control" type="date" name="from" value="<?=htmlspecialchars($from)?>"></div><div class="col-md-2"><input class="form-control" type="date" name="to" value="<?=htmlspecialchars($to)?>"></div><div class="col"><button class="btn btn-dark">Filter</button></div></form><div class="card"><div class="card-body"><table class="table datatable"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Module</th><th>Record</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['created_at'])?></td><td><?=htmlspecialchars($r['username']??'System')?></td><td><?=htmlspecialchars($r['action'])?></td><td><?=htmlspecialchars($r['module'])?></td><td><?=htmlspecialchars($r['record_type'].' #'.($r['record_id']??''))?></td><td><?=htmlspecialchars($r['ip_address']??'')?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../../templates/footer.php';
